                        raise ValueError(
                            "avg_pool1d backward intermediate must be"
                            " finite"
                        )
                    dx[j] += share
                    if not math.isfinite(dx[j]):
                        raise ValueError(
                            "avg_pool1d backward intermediate must be"
                            " finite"
                        )
        return [(parent, dx)]

    return Tensor._make(out_data, True, (parent,), backward_fn)

